Object.assign(window.I18N,{"Wer hat dich am meisten angegriffen?": "Chi ti ha attaccato di più?", "niemand besonders": "nessuno in particolare", "konnte von einem Angriff auf {0} nicht ablassen, obwohl er dort deutlich mehr verlor als gewann": "non è riuscito a rinunciare a un attacco contro {0}, pur perdendo lì molto più di quanto guadagnasse", "Sunk-Cost-Effekt": "effetto dei costi irrecuperabili", "Verlustaversion": "avversione alla perdita", "Vergeltungsimpuls": "impulso di ritorsione", "Impulsives Schnelldenken": "pensiero rapido impulsivo", "Feindseligkeitsverzerrung": "bias di attribuzione ostile", "Introspektionsillusion": "illusione di introspezione", "Selbstwertdienliche Verzerrung": "bias di autoattribuzione", "Kognitive Verzerrung – Erklärung öffnen": "Bias cognitivo – apri la spiegazione", "Psychologie": "Psicologia"});
